cite = '\n## CITE INDEX — every segment opened, each fully named\n(coverage COMPUTED by write_ch7_docket.py against the scan\'s dump: %d addresses, every one verdicted — missing 0, extra 0; Avodah Zarah 42a-54b\'s remainder %d rows enumerated outside declared scope, not opened)\n' % (len(ADDR), AZ_WHOLE - AZ_READ)
